fn has_only_one_distinct_element(a: &Vec<i32>) -> bool {
    // An empty array trivially has only one distinct element.
    if a.is_empty() {
        return true;
    }

    // Use the first element as the reference.
    let first = a[0];

    // Check that every element equals the reference.
    a.iter().all(|&x| x == first)
}

